# gzip cases, run under GNU gzip 1.14 (the oracle) and under cash's builtin. The
# compressed bytes are shown only where both make the same ones: the header with
# -n and a fixed time, the trailer, and the deflate of "hello" and of nothing, which
# miniz_oxide and zlib agree on. Everything else about compression is checked by a
# round trip; what is decompressed, listed and said is checked byte for byte. Lines
# with a tab go through od. Under -r, where GNU gzip takes the file system's order
# and cash name order, the output goes through sort.
# gzip_cases.out is GNU gzip 1.14's output.
#
# Regenerate the golden file (WSL):
#   bash gzip_cases.sh > gzip_cases.out 2>&1

exec 2>&1 </dev/null
export LC_ALL=C TZ=UTC0
unset GZIP
dir=$(mktemp -d)
cd "$dir" || exit 1
show() { od -An -c | sed 's/  */ /g; s/ *$//'; }
hex() { od -An -tx1 | sed 's/  */ /g; s/ *$//'; }
rc() { echo "rc=$?"; }
# A fixed gzip member of "hello\n" with a stored name, time and the deflate both make.
member() { printf '\037\213\010\010\245\135\015\136\000\003h\000\313\110\315\311\311\347\002\000\040\060\072\066\006\000\000\000'; }
# The same without a name or a time.
bare() { printf '\037\213\010\000\000\000\000\000\000\003\313\110\315\311\311\347\002\000\040\060\072\066\006\000\000\000'; }

