echo "== -n and -N"; gzip -nc h | gzip -lvN; gzip -Nc h | gzip -lvN; gzip -nN -c h | gzip -lvN; gzip -Nn -c h | gzip -lvN; member > nn.gz; touch -d '2021-05-06 07:08:09' nn.gz; gzip -d nn.gz; stat -c '%Y %n' nn; member > nn2.gz; touch -d '2021-05-06 07:08:09' nn2.gz; rm -f h; gzip -dN nn2.gz; rc; ls nn2* h; stat -c '%Y %n' h; member > nn3.gz; touch -d '2021-05-06 07:08:09' nn3.gz; gzip -dNv nn3.gz 2>&1 | show; rc; ls nn3* h; gzip -dNf nn3.gz; ls nn3* h; stat -c '%Y %n' h; member > nn4.gz; touch -d '2021-05-06 07:08:09' nn4.gz; gzip -dn nn4.gz; stat -c '%Y %n' nn4; bare > nn5.gz; touch -d '2021-05-06 07:08:09' nn5.gz; gzip -dN nn5.gz; stat -c '%Y %n' nn5; member > nest/x.gz; gzip -dN nest/x.gz; ls nest; cat nest/h; member | gzip -dN | hex; ls h; member | gzip -lN; printf '\037\213\010\010\000\000\000\000\000\003sub/evil\000\313\110\315\311\311\347\002\000\040\060\072\066\006\000\000\000' > ev.gz; gzip -lN ev.gz; gzip -dN ev.gz; rc; ls ev* evil; cp h ts; touch -d '2020-01-02 03:04:05' ts; gzip ts; stat -c '%Y %n' ts.gz; gzip -dN ts.gz; stat -c '%Y %n' ts; cp h old; touch -d '1960-01-01 00:00:00' old; gzip -c old | hex; rc; gzip -q -c old | hex; rc; gzip -vc old 2>&1 >/dev/null | show; cp h z0; touch -d '1970-01-01 00:00:00' z0; gzip -nc z0 | hex; rc; cp h edge; touch -d '2106-02-07 06:28:15' edge; gzip -c edge | hex; rc
